function binaryEncode(input) {
    if (input === '') return '';
    let out = '';
    for (let i = 0; i < input.length; i++) {
      const bin = input.charCodeAt(i).toString(2).padStart(16, '0');
      const bits = [];
      for (const b of bin) bits.push(b === '0' ? '喵' : '喵喵');
      out += bits.join('·') + '？';
    }
    return out + '！';
  }

